package dev.mesbase;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;import java.util.*;import java.sql.*;import java.lang.reflect.*;import java.net.*;
import dev.mesbase.platform.codegen.*;import dev.mesbase.platform.codegen.CodegenRequest.*;import dev.mesbase.platform.codegen.CodegenException.Code;
import dev.mesbase.core.factory.*;import dev.mesbase.infrastructure.catalog.*;import dev.mesbase.infrastructure.persistence.*;
/** TEST ONLY metadata and emitted Java/XML execute against isolated synthetic H2. */
class CodegenAcceptanceTest {
 @TempDir Path temp;com.zaxxer.hikari.HikariDataSource pool;MesCodegenService generator;Path backend,frontend;final java.util.concurrent.atomic.AtomicInteger rowStatements=new java.util.concurrent.atomic.AtomicInteger();
 static final String DDL="CREATE TABLE gen_demo_config(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,factory_id VARCHAR(64) NOT NULL,code VARCHAR(40) NOT NULL,name VARCHAR(100) NOT NULL,status INTEGER DEFAULT 1 NOT NULL,quantity DECIMAL(18,4),effective_at TIMESTAMP,remark VARCHAR(500),UNIQUE(factory_id,code)); COMMENT ON TABLE gen_demo_config IS 'TEST ONLY 合成配置'; COMMENT ON COLUMN gen_demo_config.code IS '编码'; COMMENT ON COLUMN gen_demo_config.name IS '名称'; COMMENT ON COLUMN gen_demo_config.status IS '状态'; COMMENT ON COLUMN gen_demo_config.quantity IS '参考数量'; COMMENT ON COLUMN gen_demo_config.effective_at IS '生效时间'; COMMENT ON COLUMN gen_demo_config.remark IS '备注';";
 @BeforeEach void setup()throws Exception{backend=temp.toRealPath().resolve("backend");frontend=temp.toRealPath().resolve("frontend");pool=RuntimeFixture.pool("metadata");try(var c=pool.getConnection();var s=c.createStatement()){s.execute(DDL);s.execute("CREATE TABLE global_config(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL)");}
  javax.sql.DataSource watched=new org.springframework.jdbc.datasource.AbstractDataSource(){public Connection getConnection()throws SQLException{return watch(pool.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return watch(pool.getConnection(u,p));}};
  generator=new DefaultMesCodegenService(new CodegenProfiles("business-dev",Map.of("business-dev",watched,"master-dev",watched,"offline",new org.springframework.jdbc.datasource.AbstractDataSource(){public Connection getConnection()throws SQLException{throw new SQLException("TEST ONLY secret connection detail PASSWORD=must-never-print");}public Connection getConnection(String u,String p)throws SQLException{return getConnection();}})));
 }
 Connection watch(Connection target){return (Connection)java.lang.reflect.Proxy.newProxyInstance(Connection.class.getClassLoader(),new Class<?>[]{Connection.class},(p,m,args)->{if(Set.of("prepareStatement","createStatement","prepareCall").contains(m.getName())){rowStatements.incrementAndGet();throw new AssertionError("Codegen must not execute business-row SQL");}try{return m.invoke(target,args);}catch(InvocationTargetException e){throw e.getCause();}});}
 @AfterEach void close(){pool.close();}
 CodegenRequest request(String datasource,boolean dry){return new CodegenRequest(datasource,"PUBLIC","gen_demo_config","testonly","合成配置","dev.mesbase.modules.testonly","TEST ONLY",ScopeKind.FACTORY_SCOPED,OverwritePolicy.FAIL,dry,backend,frontend);}
 @Test void defaultExplicitProfilesMetadataTypesCommentsIndexesNoRows(){var result=generator.generate(request(null,true));assertEquals("business-dev",result.datasource());assertEquals(CodegenResult.Status.DRY_RUN,result.status());assertEquals("master-dev",generator.generate(request("master-dev",true)).datasource());assertEquals(0,rowStatements.get());assertFalse(Files.exists(backend));assertFalse(Files.exists(frontend));var cols=result.metadata().columns();assertEquals("Long",cols.get(0).javaType());assertEquals("String",cols.get(2).javaType());assertEquals("java.math.BigDecimal",cols.get(5).javaType());assertEquals("java.time.LocalDateTime",cols.get(6).javaType());assertTrue(cols.get(5).nullable());assertEquals("1",cols.get(4).defaultValue());assertEquals("编码",cols.get(2).comment());assertTrue(result.metadata().indexes().stream().anyMatch(i->i.unique()&&i.columns().stream().anyMatch(c->c.equalsIgnoreCase("factory_id"))));assertEquals(1,cols.stream().filter(TableMetadata.Column::primaryKey).count());}
 @Test void unknownUnavailableMissingTableAreDistinctAndSafe(){assertEquals(Code.UNKNOWN_DATASOURCE,assertThrows(CodegenException.class,()->generator.generate(request("missing",true))).code());var offline=assertThrows(CodegenException.class,()->generator.generate(request("offline",true)));assertEquals(Code.DATASOURCE_UNAVAILABLE,offline.code());assertFalse(offline.getMessage().contains("secret"));var r=request(null,true);var missing=new CodegenRequest(r.datasource(),r.schema(),"not_a_table",r.moduleName(),r.businessName(),r.packageName(),r.author(),r.scope(),r.overwritePolicy(),true,backend,frontend);assertEquals(Code.TABLE_NOT_FOUND,assertThrows(CodegenException.class,()->generator.generate(missing)).code());}
 @Test void packageTraversalSymlinkAndScopeClassificationRejected()throws Exception{var r=request(null,false);assertEquals(Code.INVALID_REQUEST,assertThrows(CodegenException.class,()->generator.generate(new CodegenRequest(null,"PUBLIC",r.tableName(),"../escape",r.businessName(),r.packageName(),r.author(),r.scope(),r.overwritePolicy(),false,backend,frontend))).code());assertEquals(Code.UNSUPPORTED_SCHEMA,assertThrows(CodegenException.class,()->generator.generate(new CodegenRequest(null,"PUBLIC",r.tableName(),r.moduleName(),r.businessName(),r.packageName(),r.author(),ScopeKind.GLOBAL,r.overwritePolicy(),false,backend,frontend))).code());Path link=temp.toRealPath().resolve("link");Files.createSymbolicLink(link,temp.toRealPath());assertEquals(Code.INVALID_REQUEST,assertThrows(CodegenException.class,()->generator.generate(new CodegenRequest(null,"PUBLIC",r.tableName(),r.moduleName(),r.businessName(),r.packageName(),r.author(),r.scope(),r.overwritePolicy(),false,link,frontend))).code());}
 @Test void filesPlacedWithManifestNoCredentialsAndOverwriteConflictIsAtomic()throws Exception{var result=generator.generate(request(null,false));assertEquals(16,result.files().size());assertTrue(result.files().stream().anyMatch(f->f.path().startsWith(frontend.toString())&&f.path().endsWith("index.vue")));assertTrue(result.files().stream().anyMatch(f->f.path().endsWith("Mapper.xml")));for(var file:result.files()){String text=Files.readString(Path.of(file.path()));assertFalse(text.contains("jdbc:h2"));assertFalse(text.contains("PASSWORD=must-never-print"));assertFalse(text.contains("com.ktg"));assertFalse(text.contains("SELECT *"));assertFalse(text.contains("mf_user_factory"));}
  Path entity=Path.of(result.files().stream().filter(f->f.path().endsWith("Entity.java")).findFirst().orElseThrow().path());Files.writeString(entity,"// user-maintained file, not generated\n");String ui=Files.readString(Path.of(result.files().stream().filter(f->f.path().endsWith("index.vue")).findFirst().orElseThrow().path()));assertEquals(Code.OUTPUT_CONFLICT,assertThrows(CodegenException.class,()->generator.generate(request(null,false))).code());assertEquals(ui,Files.readString(Path.of(result.files().stream().filter(f->f.path().endsWith("index.vue")).findFirst().orElseThrow().path())));var r=request(null,false);assertEquals(Code.OUTPUT_CONFLICT,assertThrows(CodegenException.class,()->generator.generate(new CodegenRequest(null,r.schema(),r.tableName(),r.moduleName(),r.businessName(),r.packageName(),r.author(),r.scope(),OverwritePolicy.REPLACE_GENERATED,false,backend,frontend))).code());}
 @Test void generatedBackendCompilesAndScopedCrudExecutesIncludingForeignResourceIds()throws Exception{
  generator.generate(request(null,false));Path classes=temp.toRealPath().resolve("classes");Files.createDirectory(classes);var compiler=javax.tools.ToolProvider.getSystemJavaCompiler();try(var manager=compiler.getStandardFileManager(null,null,null);var files=Files.walk(backend.resolve("src/main/java"))){var units=manager.getJavaFileObjectsFromPaths(files.filter(p->p.toString().endsWith(".java")).toList());String cp=System.getProperty("java.class.path");assertTrue(compiler.getTask(null,manager,null,List.of("-classpath",cp,"-d",classes.toString(),"-parameters"),null,units).call(),"Generated Java must really compile");}
  try(var resources=Files.walk(backend.resolve("src/main/resources"))){for(Path p:resources.filter(Files::isRegularFile).toList()){Path dest=classes.resolve(backend.resolve("src/main/resources").relativize(p));Files.createDirectories(dest.getParent());Files.copy(p,dest);}}
  try(var loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},getClass().getClassLoader());var registry=new RuntimeRegistry()){
   String prefix="dev.mesbase.modules.testonly.GenDemoConfig";Thread.currentThread().setContextClassLoader(loader);Class<?> mapper=loader.loadClass(prefix+"Mapper"),serviceType=loader.loadClass(prefix+"ServiceImpl"),create=loader.loadClass(prefix+"CreateCommand"),update=loader.loadClass(prefix+"UpdateCommand"),query=loader.loadClass(prefix+"QueryDto");
   var catalog=new InMemoryFactoryCatalog(List.of(new Factory(new FactoryId("A"),"TEST","A","TEST ONLY",FactoryStatus.ENABLED)));var identity=new DatasourceIdentity("TEST-ONLY-business");var binding=new BusinessRuntimeBinding(new FactoryId("A"),identity,1);var resolver=new ConfiguredBusinessPersistenceResolver(catalog,Map.of(new FactoryId("A"),binding));registry.registerDedicated(new FactoryId("A"),identity,1,pool,()->{},Set.of(mapper));var persistence=new DedicatedDatabasePersistence(resolver,registry);Object service=serviceType.getConstructor(BusinessPersistence.class).newInstance(persistence);var scope=new FactoryScope(new FactoryId("A"));
   Object command=create.getConstructors()[0].newInstance("TEST-CODE","TEST ONLY name",1,new java.math.BigDecimal("12345678901234.1234"),java.time.LocalDateTime.parse("2026-10-05T12:30:00"),null);Object vo=serviceType.getMethod("create",FactoryScope.class,create).invoke(service,scope,command);String id=(String)vo.getClass().getMethod("id").invoke(vo);assertEquals("A",vo.getClass().getMethod("factoryId").invoke(vo));assertEquals("12345678901234.1234",vo.getClass().getMethod("quantity").invoke(vo));
   try(var c=pool.getConnection();var s=c.prepareStatement("INSERT INTO gen_demo_config(id,factory_id,code,name,status) VALUES (?,?,?,?,?)")){s.setLong(1,999);s.setString(2,"B");s.setString(3,"B-CODE");s.setString(4,"TEST ONLY foreign");s.setInt(5,1);s.executeUpdate();}
   Object q=query.getConstructors()[0].newInstance(null,null,null,null,null,null,null,null);var page=serviceType.getMethod("list",FactoryScope.class,query).invoke(service,scope,q);assertEquals(1L,page.getClass().getMethod("total").invoke(page));
   Method detail=serviceType.getMethod("detail",FactoryScope.class,Long.class);assertEquals(id,detail.invoke(service,scope,Long.valueOf(id)).getClass().getMethod("id").invoke(vo));var denial=assertThrows(InvocationTargetException.class,()->detail.invoke(service,scope,999L));assertEquals(dev.mesbase.core.error.ErrorCode.NOT_FOUND,((dev.mesbase.core.error.FoundationException)denial.getCause()).code());
   Object edit=update.getConstructors()[0].newInstance("TEST-CODE","已修改",1,null,null,"TEST ONLY update");Method change=serviceType.getMethod("update",FactoryScope.class,Long.class,update);assertThrows(InvocationTargetException.class,()->change.invoke(service,scope,999L,edit));Object modified=change.invoke(service,scope,Long.valueOf(id),edit);assertEquals("已修改",modified.getClass().getMethod("name").invoke(modified));
   Method delete=serviceType.getMethod("delete",FactoryScope.class,Long.class);assertThrows(InvocationTargetException.class,()->delete.invoke(service,scope,999L));delete.invoke(service,scope,Long.valueOf(id));assertThrows(InvocationTargetException.class,()->detail.invoke(service,scope,Long.valueOf(id)));
   var controller=loader.loadClass(prefix+"Controller");for(Method m:controller.getDeclaredMethods()){var access=m.getAnnotation(dev.mesbase.platform.web.EndpointAccess.class);assertNotNull(access);assertEquals(dev.mesbase.platform.web.EndpointAccess.Kind.AUTHORIZED,access.value());}
  }finally{Thread.currentThread().setContextClassLoader(getClass().getClassLoader());}
 }
 @Test void globalCrudUsesPlatformOwnerAndPermissionWithoutFactoryIdentity()throws Exception{var r=request("master-dev",true);var result=generator.generate(new CodegenRequest(r.datasource(),r.schema(),"global_config","testonly","全局合成配置","dev.mesbase.platform.testonly",r.author(),ScopeKind.GLOBAL,r.overwritePolicy(),false,backend,frontend));String mapper=Files.readString(Path.of(result.files().stream().filter(f->f.path().endsWith("Mapper.java")).findFirst().orElseThrow().path()));String controller=Files.readString(Path.of(result.files().stream().filter(f->f.path().endsWith("Controller.java")).findFirst().orElseThrow().path()));assertTrue(mapper.contains("Kind.PLATFORM"));assertTrue(controller.contains("PermissionScope.PLATFORM"));assertFalse(controller.contains("FactoryContext.required"));
  Path classes=temp.toRealPath().resolve("global-classes");Files.createDirectories(classes);var compiler=javax.tools.ToolProvider.getSystemJavaCompiler();try(var manager=compiler.getStandardFileManager(null,null,null);var files=Files.walk(backend.resolve("src/main/java"))){assertTrue(compiler.getTask(null,manager,null,List.of("-classpath",System.getProperty("java.class.path"),"-d",classes.toString(),"-parameters"),null,manager.getJavaFileObjectsFromPaths(files.filter(p->p.toString().endsWith(".java")).toList())).call());}
  try(var resources=Files.walk(backend.resolve("src/main/resources"))){for(Path p:resources.filter(Files::isRegularFile).toList()){Path dest=classes.resolve(backend.resolve("src/main/resources").relativize(p));Files.createDirectories(dest.getParent());Files.copy(p,dest);}}
  try(var loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},getClass().getClassLoader())){Thread.currentThread().setContextClassLoader(loader);String prefix="dev.mesbase.platform.testonly.GlobalConfig";var type=loader.loadClass(prefix+"ServiceImpl");var create=loader.loadClass(prefix+"CreateCommand");var update=loader.loadClass(prefix+"UpdateCommand");var query=loader.loadClass(prefix+"QueryDto");var persistence=new PlatformPersistence(pool,Set.of(loader.loadClass(prefix+"Mapper")));var service=type.getConstructor(PlatformPersistence.class).newInstance(persistence);var row=type.getMethod("create",create).invoke(service,create.getConstructors()[0].newInstance("GLOBAL-TEST","全局合成"));String id=(String)row.getClass().getMethod("id").invoke(row);var page=type.getMethod("list",query).invoke(service,query.getConstructors()[0].newInstance(null,null,null,null));assertEquals(1L,page.getClass().getMethod("total").invoke(page));type.getMethod("update",Long.class,update).invoke(service,Long.valueOf(id),update.getConstructors()[0].newInstance("GLOBAL-TEST","已更新"));type.getMethod("delete",Long.class).invoke(service,Long.valueOf(id));assertThrows(InvocationTargetException.class,()->type.getMethod("detail",Long.class).invoke(service,Long.valueOf(id)));}finally{Thread.currentThread().setContextClassLoader(getClass().getClassLoader());}
 }
}
